        const reportError = vi.spyOn(dialogService, 'error')
        renderAssignedWorktree(trailingWorktree)

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))
        fireEvent.click(screen.getByRole('menuitem', { name: 'Integrate into project' }))

        await vi.waitFor(() => expect(reportError).toHaveBeenCalledWith(error, {fallbackMessage: 'Could not integrate worktree into project'}))
    })
})

events.content:
import { slugifyTitle } from '../../data/card_naming'
import type { CardSeparator } from '../../data/card_identifiers'
import type {
    ProjectCard,
    ProjectReference,
    ProjectSnapshot,
    StorageService,
    WorktreeRecord,
    WorktreeState,
    WorktreeStatus,
} from '../../data/data_types'
import { register } from '.././service_injector'

interface WorktreeServiceDependencies {
    assignCardWorktree: (path: string, worktree: number | null) => void
    cardSeparatorProvider: () => CardSeparator
    flushPendingChanges: () => Promise<void>
    projectProvider: () => ProjectReference | null
    snapshotProvider: () => ProjectSnapshot | null
    storageProvider: () => StorageService | null
}

export class WorktreeService extends EventTarget {
    private adding = false
    private assignCardWorktreeValue: ((path: string, worktree: number | null) => void) | null = null
    private cardSeparatorProvider: (() => CardSeparator) | null = null
    private error: string | null = null
    private flushPendingChanges: (() => Promise<void>) | null = null
    private pendingAssignments = new Map<number, string>()
    private preparingCardPaths = new Set<string>()
    private preparingProjectWorktree = false
    private projectActionWorktree: number | null = null
    private primaryStatus: WorktreeStatus | null = null
    private projectProvider: (() => ProjectReference | null) | null = null
    private records: WorktreeRecord[] = []
    private snapshotProvider: (() => ProjectSnapshot | null) | null = null
    private storageProvider: (() => StorageService | null) | null = null
    private subscriptionCleanup: (() => void) | null = null

    constructor() {
        super()
        register('worktreeService', this)
    }

    getRecords() {
        return this.records
    }

    getProjectActionWorktree() {
        return this.projectActionWorktree
    }

    getPrimaryStatus() {
        return this.primaryStatus
    }

    /** The branch linked worktrees are rebased onto; null before a project is open. */
    getProjectBranch() {
        return this.projectProvider?.()?.branch ?? null
    }

    getError() {
        return this.error
    }

    isAdding() {
        return this.adding
    }

    isPreparingCard(path: string) {
        return this.preparingCardPaths.has(path)
    }

    isPreparingProjectWorktree() {
        return this.preparingProjectWorktree
    }

    isWorktreeAvailableForCard(worktree: number, cardPath: string) {
        const pendingOwner = this.pendingAssignments.get(worktree)
        if (pendingOwner && pendingOwner !== cardPath) return false

        return !this.activeCards().some((card) => card.path !== cardPath && card.header.worktree === worktree)
    }

    /** Whether the active storage backend can list worktrees (local desktop or a remote-controlled desktop). */
    isSupported() {
        return !!this.storageProvider?.()?.onWorktreesChanged
    }

    init(dependencies: WorktreeServiceDependencies) {
        this.subscriptionCleanup?.()
        this.assignCardWorktreeValue = dependencies.assignCardWorktree
        this.cardSeparatorProvider = dependencies.cardSeparatorProvider
        this.flushPendingChanges = dependencies.flushPendingChanges
        this.projectProvider = dependencies.projectProvider
        this.snapshotProvider = dependencies.snapshotProvider
        this.storageProvider = dependencies.storageProvider
        this.clear()
        this.subscriptionCleanup = dependencies.storageProvider()?.onWorktreesChanged?.((state) => this.handleState(state)) ?? null
    }

    clear() {
        this.projectActionWorktree = null
        this.primaryStatus = null
        this.error = null
        this.records = []
        this.dispatchChanged()
    }

    setProjectActionWorktree(worktree: number | null) {
        if (worktree !== null) {
            if (!Number.isInteger(worktree) || worktree <= 0) throw new Error(`Invalid project worktree index: ${String(worktree)}`)
            const record = this.records[worktree - 1]
            if (!record) throw new Error(`Configured worktree ${worktree} does not exist`)
            if (!record.valid) throw new Error(`Configured worktree ${worktree} is invalid: ${record.error}`)
        }
        if (this.projectActionWorktree === worktree) return

        this.projectActionWorktree = worktree
        this.dispatchChanged()
    }

    async setCardWorktree(path: string, worktree: number | null) {
        const card = this.requireCard(path)
        if (card.header.worktree === worktree && !card.header.worktreeError) return
        if (this.preparingCardPaths.has(path)) throw new Error(`Worktree preparation is already in progress for ${path}`)

        if (worktree === null) {
            if (card.header.worktreeError || card.header.worktree === null || card.header.worktree === undefined) {
                this.requireAssignmentWriter()(path, null)
                return
            }

            const storage = this.requireStorage()
            if (!storage.parkWorktree) throw new Error('Worktree parking requires Electron local mode')
            const project = this.requireProject()
            this.startCardOperation(path)
            try {
                await storage.parkWorktree({ project, worktree: card.header.worktree })
                this.requireAssignmentWriter()(path, null)
            } finally {
                this.finishCardOperation(path)
            }

            return
        }

        this.requireValidRecord(worktree)
        if (!this.isWorktreeAvailableForCard(worktree, path)) throw new Error(`Worktree ${worktree} is already assigned to another active card`)

        const storage = this.requireStorage()
        if (!storage.prepareWorktree) throw new Error('Worktree preparation requires Electron local mode')
        const project = this.requireProject()
        const branchName = slugifyTitle(`${card.header.id}-${card.header.title}`, this.requireCardSeparator())
        const request = { branchName, project, worktree }
        this.pendingAssignments.set(worktree, path)
        this.startCardOperation(path)
        try {
            await storage.prepareWorktree(request)
            if (this.requireProject() !== project) throw new Error('Opened project changed during worktree preparation')

            this.requireAssignmentWriter()(path, worktree)
        } finally {
            this.pendingAssignments.delete(worktree)
            this.finishCardOperation(path)
        }
    }

    async refresh() {
        const storage = this.requireStorage()
        const project = this.requireProject()
        if (!storage.refreshWorktrees) throw new Error('Refreshing worktrees requires Electron local mode')
        await storage.refreshWorktrees(project)
    }

    getCardCommitMessage(path: string) {
        const card = this.requireCard(path)

        return `${card.header.id}: ${card.header.title}`
    }

    async commitCardWorktree(path: string, message: string) {
        const { project, storage, worktree } = this.requireCardOperation(path)
        if (!storage.commitWorktree) throw new Error('Worktree commits require Electron local mode')

        this.startCardOperation(path)
        try {
            await storage.commitWorktree({ message, project, worktree })
        } finally {
            this.finishCardOperation(path)
        }
    }

    async integrateCardWorktree(path: string) {
        const { project, storage, worktree } = this.requireCardOperation(path)
        if (!storage.integrateWorktree) throw new Error('Worktree integration requires Electron local mode')

        this.startCardOperation(path)
        try {
            await this.requirePendingChangesFlusher()()
            await storage.integrateWorktree({ project, worktree })
        } finally {
            this.finishCardOperation(path)
        }
    }

    async updateCardWorktree(path: string) {
        const { project, storage, worktree } = this.requireCardOperation(path)
        if (!storage.rebaseWorktree) throw new Error('Worktree updates require Electron local mode')

        this.startCardOperation(path)
        try {
            await this.requirePendingChangesFlusher()()
            await storage.rebaseWorktree({ project, worktree })
        } finally {
            this.finishCardOperation(path)
        }
    }

    getProjectCommitMessage() {
        return `Update ${this.getProjectBranch() ?? 'worktree'}`
    }

    async commitProjectWorktree(message: string) {
        const { project, storage, worktree } = this.requireProjectOperation()
        if (!storage.commitWorktree) throw new Error('Worktree commits require Electron local mode')

        this.startProjectOperation()
        try {
            await storage.commitWorktree({ message, project, worktree })
        } finally {
            this.finishProjectOperation()
        }
    }

    async integrateProjectWorktree() {
        const { project, storage, worktree } = this.requireProjectOperation()
        if (!storage.integrateWorktree) throw new Error('Worktree integration requires Electron local mode')

        this.startProjectOperation()
        try {
            await this.requirePendingChangesFlusher()()
            await storage.integrateWorktree({ project, worktree })
        } finally {
            this.finishProjectOperation()
        }
    }

    async updateProjectWorktree() {
        const { project, storage, worktree } = this.requireProjectOperation()
        if (!storage.rebaseWorktree) throw new Error('Worktree updates require Electron local mode')

        this.startProjectOperation()
        try {
            await this.requirePendingChangesFlusher()()
            await storage.rebaseWorktree({ project, worktree })
        } finally {
            this.finishProjectOperation()
        }
    }

    async discardAndUnassignCardWorktree(path: string) {
        const { project, storage, worktree } = this.requireCardOperation(path)
        if (!storage.discardWorktreeChanges) throw new Error('Discarding worktree changes requires Electron local mode')
        if (!storage.parkWorktree) throw new Error('Worktree parking requires Electron local mode')

        this.startCardOperation(path)
        try {
            await storage.discardWorktreeChanges({ project, worktree })
            await storage.parkWorktree({ project, worktree })
            this.requireAssignmentWriter()(path, null)
        } finally {
            this.finishCardOperation(path)
        }
    }

    async add() {
        const storage = this.requireStorage()
        const project = this.requireProject()
        if (!storage.addWorktree) throw new Error('Worktree creation requires Electron local mode')
        if (this.adding) throw new Error('Worktree creation is already in progress')

        this.adding = true
        this.dispatchChanged()
        try {
            const added = await storage.addWorktree(project)

            return added
        } finally {
            this.adding = false
            this.dispatchChanged()
        }
    }

    async remove(index: number) {
        const storage = this.requireStorage()
        const project = this.requireProject()
        if (!storage.removeWorktree) throw new Error('Worktree removal requires Electron local mode')
        if (!Number.isInteger(index) || index < 0 || index >= this.records.length) throw new Error(`Invalid worktree list index: ${index}`)

        await storage.removeWorktree(project, this.records[index].path)
    }

    private requireProject() {
        const project = this.projectProvider?.()
        if (!project) throw new Error('Cannot save worktrees before a project is open')

        return project
    }

    private handleState(state: WorktreeState) {
        const project = this.projectProvider?.()
        if (!project || !state.project || project.id !== state.project.id || project.branch !== state.project.branch) return
        const recordsChanged = JSON.stringify(this.records) !== JSON.stringify(state.records)
        const primaryStatusChanged = JSON.stringify(this.primaryStatus) !== JSON.stringify(state.primaryStatus)
        if (!recordsChanged && !primaryStatusChanged && this.error === state.error) return

        if (recordsChanged) this.records = state.records
        if (primaryStatusChanged) this.primaryStatus = state.primaryStatus
        this.error = state.error
        this.dispatchChanged()
    }

    private activeCards() {
        return this.snapshotProvider?.()?.activeCards ?? []
    }

    private startCardOperation(path: string) {
        if (this.preparingCardPaths.has(path)) throw new Error(`Worktree operation is already in progress for ${path}`)

        this.preparingCardPaths.add(path)
        this.dispatchChanged()
    }

    private finishCardOperation(path: string) {
        this.preparingCardPaths.delete(path)
        this.dispatchChanged()
    }

    private requireCardOperation(path: string) {
        const card = this.requireCard(path)
        const worktree = card.header.worktree
        if (!Number.isInteger(worktree) || !worktree || worktree <= 0) throw new Error(`Card has no valid worktree assignment: ${path}`)

        this.requireValidRecord(worktree)

        return { project: this.requireProject(), storage: this.requireStorage(), worktree }
    }

    private startProjectOperation() {
        if (this.preparingProjectWorktree) throw new Error('Worktree operation is already in progress for the project')

        this.preparingProjectWorktree = true
        this.dispatchChanged()
    }

    private finishProjectOperation() {
        this.preparingProjectWorktree = false
        this.dispatchChanged()
    }

    private requireProjectOperation() {
        const worktree = this.projectActionWorktree
        if (!Number.isInteger(worktree) || !worktree || worktree <= 0) throw new Error('No worktree is assigned to the project')

        this.requireValidRecord(worktree)

        return { project: this.requireProject(), storage: this.requireStorage(), worktree }
    }

    private requireAssignmentWriter() {
        if (!this.assignCardWorktreeValue) throw new Error('Worktree card assignment is not initialized')

        return this.assignCardWorktreeValue
    }

    private requireCard(path: string): ProjectCard {
        const snapshot = this.snapshotProvider?.()
        const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]
        const card = cards.find((candidate) => candidate.path === path)
        if (!card) throw new Error(`Cannot assign a worktree to an unknown card: ${path}`)

        return card
    }

    private requireCardSeparator() {
        const cardSeparator = this.cardSeparatorProvider?.()
        if (!cardSeparator) throw new Error('Worktree card separator is not initialized')

        return cardSeparator
    }

    private requireValidRecord(worktree: number) {
        if (!Number.isInteger(worktree) || worktree <= 0) throw new Error(`Invalid card worktree index: ${String(worktree)}`)
        const record = this.records[worktree - 1]
        if (!record) throw new Error(`Configured worktree ${worktree} does not exist`)
        if (!record.valid) throw new Error(`Configured worktree ${worktree} is invalid: ${record.error}`)

        return record
    }

    private requireStorage() {
        const storage = this.storageProvider?.()
        if (!storage) throw new Error('Worktree service storage is not initialized')

        return storage
    }

    private requirePendingChangesFlusher() {
        if (!this.flushPendingChanges) throw new Error('Worktree pending-change flusher is not initialized')

        return this.flushPendingChanges
    }

    private dispatchChanged() {
        this.dispatchEvent(new CustomEvent('changed'))
    }
}

export const worktreeService = new WorktreeService()

import type { ActionFile } from './action_types'
import type { ActionSchedule } from './action_schedule_types'
import { DEFAULT_COLOR_SCHEME } from '../theme/theme_config'
import type { ProjectBackgroundShade } from '../theme/project_background_shade'
import { DEFAULT_CARD_SEPARATOR, type CardSeparator } from './card_identifiers'

export const DEFAULT_WORKING_FOLDER = 'active'
export const DEFAULT_ACTIONS_FOLDER = 'actions'
export const DEFAULT_ARCHIVED_FOLDER = 'archived'
export const DEFAULT_PROJECT_FOLDER = 'design'
export const DEFAULT_RELEASES_FOLDER = 'history'
export const DEFAULT_DIFF_COMMAND = 'git show {{commit}}'
export const AUTO_COMMIT_DELAY_MS = 30000

/** Card type id; projects can configure custom types beyond the default feature/job/bug. */
export type CardType = string
export type PushMode = 'auto' | 'manual'

export interface CardTypeConfig {
    color: string
    idPrefix: string
    label: string
    type: CardType
}

export interface StateConfig {
    alwaysVisible: boolean
    color?: string
    state: string
}

export interface ProjectConfig {
    actionsFolder: string
    archivedFolder: string
    backgroundShade: ProjectBackgroundShade
    cardBodyTemplate: string
    cardSeparator: CardSeparator
    cardTypes: CardTypeConfig[]
    diffCommand: string
    projectFolder: string
    pushMode: PushMode
    releasesFolder: string
    states: StateConfig[]
    workingFolder: string
}

/** How a file's `content` is encoded for the storage write path. Binary assets use base64. */
export type FileEncoding = 'utf-8' | 'base64'

export interface MarkdownFile {
    content: string
    encoding?: FileEncoding
    path: string
    sha?: string
}

export interface ProjectAsset {
    content: string
    contentType: string
    encoding: 'base64'
    path: string
}

export interface CardHeader {
    affects: string[]
    after: string | null
    /** Terminal conversation references inside activity files; the name mirrors the persisted `agents` field. */
    agentLogReferences: string[]
    author: string | null
    id: string
    internalId: string | null
    owner: string | null
    policy: Record<string, boolean>
    status: string | null
    title: string
    worktree?: number | null
    worktreeError?: string | null
    worktreeValue?: string | null
}

export interface ProjectCard {
    agentConversationErrors: AgentConversationError[]
    agentConversations: AgentConversation[]
    content: string
    header: CardHeader
    /** Raw frontmatter fields as written in the file, including unknown keys. */
    headerFields: Record<string, string | string[] | Record<string, string>>
    isActive: boolean
    path: string
    sha?: string
}

export interface ProjectSnapshot {
    activeCards: ProjectCard[]
    backgroundCards: ProjectCard[]
    repositoryFiles: string[]
    workingFolder: string
}

export interface CardDraft {
    body: string
    bodyIncludesTemplate?: boolean
    title: string
    type: CardType
}

export interface ProjectReference {
    branch: string
    id: string
    owner?: string
    repository?: string
    rootPath?: string
}

export interface WorktreeRecord {
    branch: string | null
    error: string | null
    parkingBranch: string
    path: string
    status: WorktreeStatus
    valid: boolean
}

export interface WorktreeState {
    error: string | null
    primaryStatus: WorktreeStatus | null
    project: ProjectReference | null
    records: WorktreeRecord[]
}

export interface WorktreeStatus {
    /** Commits on the worktree branch that the configured upstream lacks; 0 when there is no upstream. */
    ahead: number
    /** Commits on the worktree branch that the project branch lacks. */
    baseAhead: number
    /** Commits on the project branch that the worktree branch lacks; cleared by rebasing. */
    baseBehind: number
    /** Commits on the configured upstream that the worktree branch lacks; 0 when there is no upstream. */
    behind: number
    dirty: boolean
    hasUpstream: boolean
}

export interface PrepareWorktreeRequest {
    branchName: string
    project: ProjectReference
    worktree: number
}

export interface WorktreeOperationRequest {
    project: ProjectReference
    worktree: number
}

export interface CommitWorktreeRequest extends WorktreeOperationRequest {
    message: string
}

export interface RepositoryReference extends ProjectReference {
    owner: string
    repository: string
}

export interface BranchReference {
    name: string
}

export interface TopLevelFolderReference {
    name: string
    path: string
}

export const MISSING_WORKING_FOLDER_ERROR = 'missing-working-folder'

export class MissingWorkingFolderError extends Error {
    code: typeof MISSING_WORKING_FOLDER_ERROR
    workingFolder: string

    constructor(workingFolder: string) {
        super(`Working folder is missing: ${workingFolder}`)
        this.code = MISSING_WORKING_FOLDER_ERROR
        this.workingFolder = workingFolder
    }
}

export interface CommitRequest {
    branch: string
    files: MarkdownFile[]
    message: string
    moves?: MoveFile[]
}

export type CommitResult = MarkdownFile[]

export interface MoveFile {
    content: string
    encoding?: FileEncoding
    fromPath: string
    sha?: string
    toPath: string
}

export interface MoveFilesRequest {
    branch: string
    message: string
    moves: MoveFile[]
}

export interface DeleteFileRequest {
    branch: string
    message: string
    path: string
    sha?: string
}

export interface DeleteFolderRequest {
    branch: string
    message: string
    path: string
}

export type ProjectWatchChangeKind = 'added' | 'changed' | 'removed' | 'unknown'

export interface ProjectWatchEvent {
    changeKind: ProjectWatchChangeKind
    path: string
}

/** A background agent/action currently running against a card or file. */
export interface RunningAgent {
    id: string
    label: string
}

export type AgentConversationStatus = 'cancelled' | 'completed' | 'failed' | 'running' | 'waitingForInput'
export type AgentMessageRole = 'assistant' | 'user'

export interface AgentConversationMessage {
    agent?: string
    content: string
    id: string
    role: AgentMessageRole
    sequence?: number
    timestamp: string
}

export interface AgentProviderSession {
    agent: string
    conversationId: string
    createdAt: string
    lastUsedAt: string
    synchronizedThroughMessageId: string
}

export interface AgentConversationEvent {
    command?: string
    content: string
    details?: string[]
    durationMs?: number
    exitCode?: number
    id: string
    label?: string
    output?: string
    providerItemId?: string
    sequence?: number
    status?: string
    summary?: string[]
    timestamp: string
    type: string
    workingDirectory?: string
}

export interface AgentTokenUsage {
    cachedInputTokens: number
    costUsd?: number
    inputTokens: number
    outputTokens: number
    reasoningTokens: number
    totalTokens: number
}

export interface AgentConversation {
    actionId?: string | null
    cardInternalId?: string | null
    cardPath: string | null
    completedAt: string | null
    events: AgentConversationEvent[]
    hasExplicitTitle: boolean
    id: string
    messages: AgentConversationMessage[]
    path: string
    providerSessions: AgentProviderSession[]
    startedAt: string
    status: AgentConversationStatus
    title: string
    usage?: AgentTokenUsage
}

export interface AgentConversationError {
    message: string
    path: string
}

export type AgentRunEvent =
    | {
        conversationId: string
        reference: string
        runId: string
        startedAt: string
        title: string
        type: 'started'
        userMessage: AgentConversationMessage
    }
    | {
        activity: AgentConversationEvent
        runId: string
        type: 'agentActivity'
    }
    | {
        content: string
        runId: string
        type: 'error' | 'output'
    }
    | {
        reference: string
        runId: string
        status: AgentConversationStatus
        type: 'closed'
    }

export interface StorageProjectFiles {
    files: MarkdownFile[]
    workingFolder: string
}

export interface StorageService {
    addWorktree?(project: ProjectReference): Promise<boolean>
    checkoutBranch(project: ProjectReference, branch: string): Promise<ProjectReference>
    commit(request: CommitRequest): Promise<CommitResult>
    commitWorktree?(request: CommitWorktreeRequest): Promise<void>
    createProject(project: ProjectReference, workingFolder: string): Promise<ProjectReference>
    deleteFile(request: DeleteFileRequest): Promise<void>
    deleteFolder(request: DeleteFolderRequest): Promise<void>
    discardWorktreeChanges?(request: WorktreeOperationRequest): Promise<void>
    discardPendingCommits?(project: ProjectReference): void
    hasPendingPush?(project: ProjectReference): boolean
    listBranches(project: ProjectReference): Promise<BranchReference[]>
    listAgentConversationReferences?(project: ProjectReference, projectFolder: string): Promise<string[]>
    listRepositories(): Promise<RepositoryReference[]>
    loadActionFiles(project: ProjectReference, actionsFolder: string): Promise<ActionFile[]>
    loadActionSchedules?(project: ProjectReference, actionsFolder: string): Promise<ActionSchedule[]>
    cancelActionSchedule?(project: ProjectReference, actionsFolder: string, scheduleId: string): Promise<ActionSchedule[]>
    loadAgentConversation?(project: ProjectReference, path: string): Promise<AgentConversation>
    loadProjectAsset?(project: ProjectReference, path: string): Promise<ProjectAsset>
    loadProject(project: ProjectReference, workingFolder: string): Promise<StorageProjectFiles>
    loadFile?(project: ProjectReference, path: string): Promise<MarkdownFile>
    loadProjectRoot(project: ProjectReference, workingFolder: string): Promise<StorageProjectFiles>
    loadProjectConfig(project: ProjectReference): Promise<Partial<ProjectConfig> | null>
    onWorktreesChanged?(callback: (state: WorktreeState) => void): () => void
    restorePendingCommits?(project: ProjectReference): Promise<void>
    resolveProject?(project: ProjectReference): Promise<ProjectReference>
    listRepositoryFiles(project: ProjectReference): Promise<string[]>
    listTopLevelFolders(project: ProjectReference): Promise<TopLevelFolderReference[]>
    loadPendingPush?(project: ProjectReference): Promise<void>
    integrateWorktree?(request: WorktreeOperationRequest): Promise<void>
    moveFiles(request: MoveFilesRequest): Promise<void>
    parkWorktree?(request: WorktreeOperationRequest): Promise<void>
    prepareWorktree?(request: PrepareWorktreeRequest): Promise<void>
    pull?(project: ProjectReference): Promise<void>
    pullWorktree?(request: WorktreeOperationRequest): Promise<void>
    rebaseWorktree?(request: WorktreeOperationRequest): Promise<void>
    push(project: ProjectReference): Promise<void>
    pushWorktree?(request: WorktreeOperationRequest): Promise<void>
    refreshWorktrees?(project: ProjectReference): Promise<void>
    saveActionSchedules?(project: ProjectReference, actionsFolder: string, schedules: ActionSchedule[]): Promise<ActionSchedule[]>
    saveProjectConfig(project: ProjectReference, config: ProjectConfig): Promise<void>
    removeWorktree?(project: ProjectReference, folderPath: string): Promise<void>
    stopAgent?(project: ProjectReference, runId: string): Promise<void>
    watchProject?(project: ProjectReference, onChange: (event: ProjectWatchEvent) => void): () => void
}

const BUG_CARD_COLOR = '#d32f2f'

export const DEFAULT_COLUMN_ACCENTS = ['#9c4dcc', '#29a8e0', '#ed6c02', '#f9a825', '#43a047']

/** Resolve the repeating default accent assigned by configured column position. */
export function defaultColumnAccent(index: number) {
    if (!Number.isInteger(index) || index < 0) throw new Error(`Invalid column index: ${index}`)

    return DEFAULT_COLUMN_ACCENTS[index % DEFAULT_COLUMN_ACCENTS.length]
}

export const DEFAULT_CARD_TYPES: CardTypeConfig[] = [
    { color: DEFAULT_COLOR_SCHEME.primary.regular, idPrefix: 'F', label: 'Feature', type: 'feature' },
    { color: DEFAULT_COLOR_SCHEME.secondary.regular, idPrefix: 'J', label: 'Job', type: 'job' },
    { color: BUG_CARD_COLOR, idPrefix: 'B', label: 'Bug', type: 'bug' },
]

export const DEFAULT_STATES: StateConfig[] = [
    { alwaysVisible: true, color: defaultColumnAccent(0), state: 'new' },
    { alwaysVisible: true, color: defaultColumnAccent(1), state: 'design' },
    { alwaysVisible: true, color: defaultColumnAccent(2), state: 'ready for implementation' },
    { alwaysVisible: true, color: defaultColumnAccent(3), state: 'in progress' },
    { alwaysVisible: true, color: defaultColumnAccent(4), state: 'done' },
]

export const DEFAULT_CARD_BODY_TEMPLATE = '# Goal\n\n# Current status\n\n# Details\n\n# Tasks'

function normalizeFolderPath(folderPath: string) {
    return folderPath.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
}

function joinProjectFolderPath(projectFolder: string, folderPath: string) {
    const normalizedProjectFolder = normalizeFolderPath(projectFolder)
    const normalizedFolderPath = normalizeFolderPath(folderPath)

    return normalizedProjectFolder.length > 0 ? `${normalizedProjectFolder}/${normalizedFolderPath}` : normalizedFolderPath
}

export function resolveProjectConfigPaths(config: ProjectConfig): ProjectConfig {
    return {
        ...config,
        actionsFolder: joinProjectFolderPath(config.projectFolder, config.actionsFolder),
        archivedFolder: joinProjectFolderPath(config.projectFolder, config.archivedFolder),
        releasesFolder: joinProjectFolderPath(config.projectFolder, config.releasesFolder),
        workingFolder: joinProjectFolderPath(config.projectFolder, config.workingFolder),
    }
}

