import type { AgentConversation } from '../app/src/data/data_types'

export type ActivityOrigin = { kind: 'card'; cardInternalId: string } | { kind: 'project' }
export type ActionActivityStatus = 'cancelled' | 'completed' | 'failed' | 'okButNotAfter'

export interface ActivityCommitReference {
    available?: boolean
    actionId?: string
    actionName?: string
    branch: string
    commit: string
    committedAt: string
    deletions: number
    filePaths: string[]
    filesChanged: number
    insertions: number
}

export interface ActionActivityRecord {
    commits: ActivityCommitReference[]
    completedAt: string
    conversationIds: string[]
    executionId: string
    history: {
        agent?: string | null
        command?: string
        completedAt: string
        model?: string
        output: string
        prompt: string
        status: 'completed' | 'failed'
        thinkingLevel?: string
    }
    origin: ActivityOrigin
    rootActionId: string
    rootActionLabel: string
    startedAt: string
    status: ActionActivityStatus
}

export interface CardActivityFile {
    conversations: Omit<AgentConversation, 'path'>[]
    origin: ActivityOrigin
    records: ActionActivityRecord[]
    version: 1
}

export function createActivityFile(origin: ActivityOrigin): CardActivityFile
export function parseActivityValue(value: unknown, expectedOrigin?: ActivityOrigin | null): CardActivityFile
export function parseActivityFile(content: string, expectedOrigin?: ActivityOrigin | null): CardActivityFile
export function findActivityConversation(activity: CardActivityFile, conversationId: string): Omit<AgentConversation, 'path'>

import { parseAgentConversation } from './agent_conversations.mjs'

const ACTIVITY_VERSION = 1
const ACTION_ACTIVITY_STATUSES = new Set(['cancelled', 'completed', 'failed', 'okButNotAfter'])

function requiredString(value, fieldName, allowEmpty = false) {
    if (typeof value !== 'string' || (!allowEmpty && value.length === 0)) throw new Error(`Malformed activity file: missing ${fieldName}`)

    return value
}

function requiredTimestamp(value, fieldName) {
    const timestamp = requiredString(value, fieldName)
    if (Number.isNaN(Date.parse(timestamp))) throw new Error(`Malformed activity file: invalid ${fieldName}`)

    return timestamp
}

function nonNegativeInteger(value, fieldName) {
    if (!Number.isInteger(value) || value < 0) throw new Error(`Malformed activity file: invalid ${fieldName}`)

    return value
}

function requiredStringArray(value, fieldName) {
    if (!Array.isArray(value)) throw new Error(`Malformed activity file: invalid ${fieldName}`)

    return value.map((entry, index) => requiredString(entry, `${fieldName}[${index}]`))
}

function parseOrigin(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Malformed activity file: missing origin')
    if (value.kind === 'project') return { kind: 'project' }
    if (value.kind !== 'card') throw new Error(`Malformed activity file: invalid origin kind ${String(value.kind)}`)

    return { cardInternalId: requiredString(value.cardInternalId, 'origin.cardInternalId'), kind: 'card' }
}

function sameOrigin(first, second) {
    return first.kind === second.kind && first.cardInternalId === second.cardInternalId
}

function parseCommit(value, index) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid commits[${index}]`)
    const commit = {
        branch: requiredString(value.branch, `commits[${index}].branch`),
        commit: requiredString(value.commit, `commits[${index}].commit`),
        committedAt: requiredTimestamp(value.committedAt, `commits[${index}].committedAt`),
        deletions: nonNegativeInteger(value.deletions, `commits[${index}].deletions`),
        filePaths: requiredStringArray(value.filePaths, `commits[${index}].filePaths`),
        filesChanged: nonNegativeInteger(value.filesChanged, `commits[${index}].filesChanged`),
        insertions: nonNegativeInteger(value.insertions, `commits[${index}].insertions`),
    }
    if (!/^[0-9a-f]{40}$/iu.test(commit.commit)) throw new Error(`Malformed activity file: invalid commits[${index}].commit`)
    if (value.available !== undefined) {
        if (typeof value.available !== 'boolean') throw new Error(`Malformed activity file: invalid commits[${index}].available`)
        commit.available = value.available
    }
    if (value.actionId !== undefined || value.actionName !== undefined) {
        commit.actionId = requiredString(value.actionId, `commits[${index}].actionId`)
        commit.actionName = requiredString(value.actionName, `commits[${index}].actionName`)
    }

    return commit
}

function parseHistory(value, index) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid records[${index}].history`)
    const status = requiredString(value.status, `records[${index}].history.status`)
    if (status !== 'completed' && status !== 'failed') throw new Error(`Malformed activity file: invalid records[${index}].history.status`)
    const history = {
        completedAt: requiredTimestamp(value.completedAt, `records[${index}].history.completedAt`),
        output: requiredString(value.output, `records[${index}].history.output`, true),
        prompt: requiredString(value.prompt, `records[${index}].history.prompt`, true),
        status,
    }
    for (const fieldName of ['agent', 'command', 'model', 'thinkingLevel']) {
        if (value[fieldName] === undefined) continue
        if (fieldName === 'agent' && value[fieldName] === null) history[fieldName] = null
        else history[fieldName] = requiredString(value[fieldName], `records[${index}].history.${fieldName}`)
    }

    return history
}

function parseRecord(value, index, activityOrigin) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid records[${index}]`)
    const status = requiredString(value.status, `records[${index}].status`)
    if (!ACTION_ACTIVITY_STATUSES.has(status)) throw new Error(`Malformed activity file: invalid records[${index}].status`)
    if (!Array.isArray(value.commits)) throw new Error(`Malformed activity file: invalid records[${index}].commits`)
    if (!Array.isArray(value.conversationIds)) throw new Error(`Malformed activity file: invalid records[${index}].conversationIds`)

    const origin = parseOrigin(value.origin)
    if (!sameOrigin(origin, activityOrigin)) throw new Error(`Malformed activity file: records[${index}].origin does not match activity origin`)

    return {
        commits: value.commits.map(parseCommit),
        completedAt: requiredTimestamp(value.completedAt, `records[${index}].completedAt`),
        conversationIds: requiredStringArray(value.conversationIds, `records[${index}].conversationIds`),
        executionId: requiredString(value.executionId, `records[${index}].executionId`),
        history: parseHistory(value.history, index),
        origin,
        rootActionId: requiredString(value.rootActionId, `records[${index}].rootActionId`),
        rootActionLabel: requiredString(value.rootActionLabel, `records[${index}].rootActionLabel`),
        startedAt: requiredTimestamp(value.startedAt, `records[${index}].startedAt`),
        status,
    }
}

function parseConversation(value, index, activityOrigin) {
    try {
        const parsed = parseAgentConversation(JSON.stringify(value), '')
        const expectedCardInternalId = activityOrigin.kind === 'card' ? activityOrigin.cardInternalId : null
        if (parsed.cardInternalId !== expectedCardInternalId) throw new Error('conversation cardInternalId does not match activity origin')

        return Object.fromEntries(Object.entries(parsed).filter(([fieldName]) => fieldName !== 'path'))
    } catch (error) {
        const detail = error instanceof Error ? error.message : 'invalid conversation'
        throw new Error(`Malformed activity file: conversations[${index}] ${detail}`, { cause: error })
    }
}

export function createActivityFile(origin) {
    return { conversations: [], origin: parseOrigin(origin), records: [], version: ACTIVITY_VERSION }
}

export function parseActivityValue(value, expectedOrigin = null) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Malformed activity file: root must be an object')
    if (value.version !== ACTIVITY_VERSION) throw new Error(`Malformed activity file: unsupported version ${String(value.version)}`)
    if (!Array.isArray(value.records)) throw new Error('Malformed activity file: records must be an array')
    if (!Array.isArray(value.conversations)) throw new Error('Malformed activity file: conversations must be an array')
    const origin = parseOrigin(value.origin)
    if (expectedOrigin) {
        const expected = parseOrigin(expectedOrigin)
        if (!sameOrigin(origin, expected)) {
            throw new Error('Malformed activity file: origin does not match requested activity')
        }
    }

    return {
        conversations: value.conversations.map((conversation, index) => parseConversation(conversation, index, origin)),
        origin,
        records: value.records.map((record, index) => parseRecord(record, index, origin)),
        version: ACTIVITY_VERSION,
    }
}

export function parseActivityFile(content, expectedOrigin = null) {
    return parseActivityValue(JSON.parse(content), expectedOrigin)
}

export function findActivityConversation(activity, conversationId) {
    const conversation = activity.conversations.find(({ id }) => id === conversationId)
    if (!conversation) throw new Error(`Activity conversation not found: ${conversationId}`)
    return conversation
}

import type { ActivityCommitReference, ActionActivityRecord, CardActivityFile } from '../../../../shared/card_activity.mjs'
import { parseActivityValue } from '../../../../shared/card_activity.mjs'
import { getElectronActionBridge } from '../../data/electron_action_bridge'
import { markdownParsingService } from '../data/markdown_parsing_service'

export interface CardCommit extends ActivityCommitReference {
    record: ActionActivityRecord
}

export interface CardBodyDiff {
    newBody: string
    newExists: boolean
    oldBody: string
    oldExists: boolean
}

/** Load visible commits for one stable card identity, newest first. */
export async function loadCardCommits(cardInternalId: string): Promise<CardCommit[]> {
    const bridge = getElectronActionBridge()
    if (!bridge?.loadCardActivity) return []
    const rawActivity = await bridge.loadCardActivity({ cardInternalId })
    const activity = parseActivityValue(rawActivity, { cardInternalId, kind: 'card' }) as CardActivityFile

    return activity.records
        .flatMap((record) => record.commits.map((commit) => ({ ...commit, record })))
        .sort((left, right) => right.committedAt.localeCompare(left.committedAt))
}

/** Read both historical card revisions and exclude frontmatter from diff input. */
export async function loadCardBodyDiff(commit: CardCommit, path: string): Promise<CardBodyDiff> {
    if (commit.available === false) throw new Error('Commit is no longer available in this repository')
    const bridge = getElectronActionBridge()
    if (!bridge?.readFileAtCommit) throw new Error('Card commit diff requires Electron local mode')
    const [oldFile, newFile] = await Promise.all([
        bridge.readFileAtCommit({ commit: commit.commit, parent: true, path }),
        bridge.readFileAtCommit({ commit: commit.commit, parent: false, path }),
    ])

    return {
        newBody: newFile.exists ? markdownParsingService.parse(newFile.content).body : '',
        newExists: newFile.exists,
        oldBody: oldFile.exists ? markdownParsingService.parse(oldFile.content).body : '',
        oldExists: oldFile.exists,
    }
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { dataService } from '../../services/data/data_service'
import { actionExecutionService } from '../../services/actions/action_execution_service'
import { loadCardCommits, type CardCommit } from '../../services/actions/card_commit_history'
import { worktreeService } from '../../services/project/worktree_service'
import type { ProjectReference } from '../../data/data_types'

interface CardCommitsState {
    commits: CardCommit[]
    error: Error | null
    loading: boolean
    reload: () => void
}

interface CardCommitsResult {
    cardInternalId: string | null
    commits: CardCommit[]
    error: Error | null
    reloadNonce: number
}

function projectKey(project: ProjectReference | null) {
    return project ? `${project.id}\u0000${project.branch}` : ''
}

/** Load one card's visible commit history and refresh it when repository state changes. */
export function useCardCommits(cardInternalId: string | null): CardCommitsState {
    const requestId = useRef(0)
    const currentProjectKey = useRef(projectKey(dataService.getState().project))
    const [result, setResult] = useState<CardCommitsResult>({ cardInternalId: null, commits: [], error: null, reloadNonce: -1 })
    const [reloadNonce, setReloadNonce] = useState(0)
    const reload = useCallback(() => setReloadNonce((current) => current + 1), [])

    useEffect(() => {
        const handleActionEvent = (event: Parameters<Parameters<typeof actionExecutionService.subscribeEvents>[0]>[0]) => {
            if (event.type !== 'execution' || event.status === 'running') return
            if (event.context.cardInternalId === cardInternalId) reload()
        }
        const handleProjectChange = () => {
            const nextProjectKey = projectKey(dataService.getState().project)
            if (nextProjectKey === currentProjectKey.current) return
            currentProjectKey.current = nextProjectKey
            reload()
        }
        const unsubscribeAction = actionExecutionService.subscribeEvents(handleActionEvent)
        worktreeService.addEventListener('changed', reload)
        dataService.addEventListener('changed', handleProjectChange)
        dataService.addEventListener('repositoryChanged', reload)

        return () => {
            unsubscribeAction()
            worktreeService.removeEventListener('changed', reload)
            dataService.removeEventListener('changed', handleProjectChange)
            dataService.removeEventListener('repositoryChanged', reload)
        }
    }, [cardInternalId, reload])

    useEffect(() => {
        requestId.current += 1
        const currentRequestId = requestId.current
        if (!cardInternalId) return undefined
        void loadCardCommits(cardInternalId).then((nextCommits) => {
            if (requestId.current !== currentRequestId) return
            setResult({ cardInternalId, commits: nextCommits, error: null, reloadNonce })
        }).catch((loadError: unknown) => {
            if (requestId.current !== currentRequestId) return
            const error = loadError instanceof Error ? loadError : new Error('Could not load card commit history')
            setResult({ cardInternalId, commits: [], error, reloadNonce })
        })

        return () => {
            if (requestId.current === currentRequestId) requestId.current += 1
        }
    }, [cardInternalId, reloadNonce])

    const isCurrent = result.cardInternalId === cardInternalId && result.reloadNonce === reloadNonce

    return {
        commits: isCurrent ? result.commits : [],
        error: isCurrent ? result.error : null,
        loading: cardInternalId !== null && !isCurrent,
        reload,
    }
}

import { Badge, Box, Divider, IconButton, Popover, Stack, Tooltip, Typography } from '@mui/material'
import SourceCommit from 'mdi-material-ui/SourceCommit'
import type { MouseEvent } from 'react'
import { useState } from 'react'
import type { CardCommit } from '../../services/actions/card_commit_history'
import { dialogService } from '../../services/dialog_service'

interface CardCommitMenuProps {
    commits: CardCommit[]
    error: Error | null
    onSelect: (commit: CardCommit) => void
}

function commitDate(timestamp: string) {
    return new Intl.DateTimeFormat(undefined, { dateStyle: 'short', timeStyle: 'short' }).format(new Date(timestamp))
}

/** Commit-history menu shared by board-card and file-card surfaces. */
export function CardCommitMenu(props: CardCommitMenuProps) {
    const { commits, error, onSelect } = props
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
    const handleOpen = (event: MouseEvent<HTMLElement>) => setAnchorElement(event.currentTarget)
    const handleClose = () => setAnchorElement(null)
    const selectCommit = (event: MouseEvent<HTMLButtonElement>) => {
        try {
            const commitIndex = Number(event.currentTarget.dataset.commitIndex)
            const commit = commits[commitIndex]
            if (!Number.isInteger(commitIndex) || !commit) throw new Error(`Card commit menu selection not found: ${commitIndex}`)
            onSelect(commit)
            handleClose()
        } catch (caught) {
            dialogService.error(caught, { fallbackMessage: 'Card commit could not be selected' })
        }
    }

    if (error) {
        return <Typography color="error" role="alert" title={error.message} variant="caption">Commit history unavailable</Typography>
    }
    if (commits.length === 0) return null

    return (
        <>
            <Tooltip title="Card commit history">
                <IconButton aria-label="Card commit history" onClick={handleOpen} size="small" sx={{ height: 30, width: 12, p: 0 }}>
                    <Badge badgeContent={commits.length > 1 ? commits.length : 0} color="primary">
                        <SourceCommit sx={{ fontSize: 17 }} />
                    </Badge>
                </IconButton>
            </Tooltip>
            <Divider orientation="vertical" sx={{ borderColor: 'divider', height: 20 }} />
            <Popover anchorEl={anchorElement} onClose={handleClose} open={!!anchorElement}>
                <Stack sx={{ maxHeight: 360, minWidth: 340, overflowY: 'auto', p: 1 }}>
                    {commits.map((commit, commitIndex) => (
                        <Box
                            component="button"
                            data-commit-index={commitIndex}
                            key={`${commit.record.executionId}:${commit.commit}:${commitIndex}`}
                            onClick={selectCommit}
                            title={commit.commit}
                            sx={{
                                '&:hover': { bgcolor: 'action.hover' },
                                background: 'none',
