\r\n    return render(mainWindowElement(overrides))\r\n}\r\n\r\nfunction installAgentBridge(stdout: string) {\r\n    const bridge: ElectronActionBridge = {\r\n        cancelActionExecution: vi.fn(async () => {}),\r\n        generateDiff: vi.fn(async () => ({ commit: '', files: [] })),\r\n        loadActionRunHistory: vi.fn(async () => []),\r\n        onActionExecution: vi.fn(() => () => {}),\r\n        openInEditor: vi.fn(async () => {}),\r\n        prepareActionPrompt: vi.fn(async () => ({ prompt: '' })),\r\n        runSearchRegexpAgent: vi.fn(async () => stdout),\r\n        startAction: vi.fn(async () => 'action-1'),\r\n    }\r\n    window.md2Actions = bridge\r\n\r\n    return bridge\r\n}\r\n\r\nfunction createStorage(files: MarkdownFile[] = []): StorageService {\r\n    return {\r\n        checkoutBranch: vi.fn(async (project, branch) => ({ ...project, branch })),\r\n        commit: vi.fn(async () => []),\r\n        createProject: vi.fn(async (project) => project),\r\n        deleteFile: vi.fn(),\r\n        deleteFolder: vi.fn(),\r\n        listBranches: vi.fn(async () => []),\r\n        listRepositories: vi.fn(async () => []),\r\n        listRepositoryFiles: vi.fn(async () => []),\r\n        listTopLevelFolders: vi.fn(async () => []),\r\n        loadActionFiles: vi.fn(async () => []),\r\n        loadProject: vi.fn(async () => ({ files, workingFolder: 'design' })),\r\n        loadProjectRoot: vi.fn(async () => ({ files, workingFolder: 'design' })),\r\n        loadProjectConfig: vi.fn(async () => ({ backgroundShade: 'blue' as const, projectFolder: '', workingFolder: 'design' })),\r\n        moveFiles: vi.fn(),\r\n        push: vi.fn(),\r\n        saveProjectConfig: vi.fn(),\r\n    }\r\n}\r\n\r\nasync function openProjectWithCards() {\r\n    const files = [\r\n        { content: '---\\nid: F-1\\ntitle: Root\\nstatus: active\\naffects:\\n---\\n\\n# Root', path: 'design/F-1-root.md' },\r\n        { content: '# Old', path: 'design/history/F-2-old.md' },\r\n    ]\r\n    openFilesService.init({ actionService, dataService })\r\n    projectPersistenceService.init({ actionService, dataService, openFilesService })\r\n    dataService.init({ storage: createStorage(files) })\r\n    const project = { branch: 'main', id: 'project', rootPath: 'C:/project' }\r\n    const snapshot = await dataService.projectLoading.openProject(project)\r\n\r\n    return { project, snapshot, storageType: 'local' as const }\r\n}\r\n\r\nfunction typeQuery(value: string) {\r\n    fireEvent.focus(screen.getByRole('textbox', { name: 'Search project' }))\r\n    fireEvent.change(screen.getByRole('textbox', { name: 'Search project' }), { target: { value } })\r\n}\r\n\r\nfunction mockMatchMedia(matches: boolean) {\r\n    window.matchMedia = ((query: string) => ({\r\n        addEventListener: () => {},\r\n        addListener: () => {},\r\n        dispatchEvent: () => false,\r\n        matches,\r\n        media: query,\r\n        onchange: null,\r\n        removeEventListener: () => {},\r\n        removeListener: () => {},\r\n    })) as unknown as typeof window.matchMedia\r\n}\r\n\r\ndescribe('MainWindow', () => {\r\n    beforeEach(() => {\r\n        configService.init({ desktopConfig: null })\r\n        openFilesService.init({ actionService, dataService })\r\n        projectPersistenceService.init({ actionService, dataService, openFilesService })\r\n        dataService.init({ storage: createStorage() })\r\n    })\r\n\r\n    afterEach(() => {\r\n        cleanup()\r\n        dataService.init({ storage: createStorage() })\r\n        configService.clear()\r\n        delete window.md2Actions\r\n        window.location.hash = ''\r\n        workspaceViewService.setViewMode('cards')\r\n        mockMatchMedia(false)\r\n    })\r\n\r\n    it('shows the workspace and status bar on desktop', () => {\r\n        mockMatchMedia(false)\r\n        renderWindow()\r\n\r\n        expect(screen.getByRole('button', { name: 'GitHub account' })).toBeInTheDocument()\r\n        expect(screen.getByRole('button', { name: 'Open project' })).toBeInTheDocument()\r\n        expect(screen.getByRole('heading', { name: 'No project open' })).toBeInTheDocument()\r\n        expect(screen.getByRole('button', { name: 'Running agents: 0' })).toBeInTheDocument()\r\n        expect(screen.queryByRole('button', { name: 'Open menu' })).toBeNull()\r\n    })\r\n\r\n    it('shows card columns without a left navigation panel in card view', async () => {\r\n        mockMatchMedia(false)\r\n        await openProjectWithCards()\r\n        renderWindow()\r\n\r\n        expect(screen.getByLabelText('Card columns')).toHaveTextContent('active')\r\n        expect(within(screen.getByLabelText('Card columns')).getByText('Root')).toBeInTheDocument()\r\n        expect(screen.getByRole('contentinfo')).toHaveTextContent('2cards')\r\n        expect(screen.getByRole('contentinfo')).toHaveTextContent('1active')\r\n        expect(screen.queryByText('No project navigation available.')).toBeNull()\r\n        expect(screen.queryByRole('separator', { name: 'Resize panels' })).toBeNull()\r\n        expect(screen.getByLabelText('File tree')).not.toBeVisible()\r\n    })\r\n\r\n    it('keeps text navigation hidden when the first project opens in card view', async () => {\r\n        mockMatchMedia(false)\r\n        renderWindow()\r\n\r\n        expect(screen.queryByRole('separator', { name: 'Resize panels' })).toBeNull()\r\n\r\n        await openProjectWithCards()\r\n\r\n        await waitFor(() => {\r\n            expect(screen.getByLabelText('Card columns')).toHaveTextContent('active')\r\n            expect(screen.queryByRole('separator', { name: 'Resize panels' })).toBeNull()\r\n            expect(screen.getByLabelText('File tree')).not.toBeVisible()\r\n        })\r\n    })\r\n\r\n    it('switches from card view to text view on desktop without resetting back to cards', async () => {\r\n        mockMatchMedia(false)\r\n        await openProjectWithCards()\r\n        renderWindow()\r\n\r\n        fireEvent.click(screen.getByRole('button', { name: 'Text view' }))\r\n\r\n        expect(await screen.findByLabelText('File tree')).toBeInTheDocument()\r\n        expect(screen.queryByRole('heading', { name: 'Files' })).toBeNull()\r\n        expect(screen.getByRole('separator', { name: 'Resize panels' })).toBeInTheDocument()\r\n    })\r\n\r\n    it('keeps the project workspace mounted while switching desktop views', async () => {\r\n        mockMatchMedia(false)\r\n        await openProjectWithCards()\r\n        renderWindow()\r\n        const workspace = screen.getByLabelText('Project workspace')\r\n\r\n        fireEvent.click(screen.getByRole('button', { name: 'Text view' }))\r\n        await screen.findByLabelText('File tree')\r\n\r\n        expect(screen.getByLabelText('Project workspace')).toBe(workspace)\r\n\r\n        fireEvent.click(screen.getByRole('button', { name: 'Cards view' }))\r\n\r\n        expect(screen.getByLabelText('Project workspace')).toBe(workspace)\r\n    })\r\n\r\n    it('moves the left panel content into a hamburger drawer on mobile', () => {\r\n        mockMatchMedia(true)\r\n        renderWindow()\r\n\r\n        expect(screen.queryByLabelText('Personal access token')).toBeNull()\r\n        expect(screen.queryByRole('button', { name: /Switch to (dark|light) theme/ })).toBeNull()\r\n        fireEvent.click(screen.getByRole('button', { name: 'Open menu' }))\r\n        expect(screen.getByText('No project navigation available.')).toBeInTheDocument()\r\n        expect(screen.getByRole('button', { name: /Switch to (dark|light) theme/ })).toBeInTheDocument()\r\n        expect(screen.queryByLabelText('Personal access token')).toBeNull()\r\n    })\r\n\r\n    it('opens mobile search from a toolbar icon', () => {\r\n        mockMatchMedia(true)\r\n        renderWindow()\r\n\r\n        expect(screen.queryByRole('textbox', { name: 'Search project' })).toBeNull()\r\n\r\n        fireEvent.click(screen.getByRole('button', { name: 'Search' }))\r\n\r\n        expect(screen.getByRole('textbox', { name: 'Search project' })).toHaveFocus()\r\n    })\r\n\r\n    it('keeps GitHub authentication in the mobile drawer footer', () => {\r\n        mockMatchMedia(true)\r\n        renderWindow()\r\n\r\n        expect(screen.queryByRole('button', { name: 'GitHub account' })).toBeNull()\r\n        fireEvent.click(screen.getByRole('button', { name: 'Open menu' }))\r\n        const drawerFooter = screen.getByRole('contentinfo')\r\n        fireEvent.click(within(drawerFooter).getByRole('button', { name: 'GitHub account' }))\r\n\r\n        expect(screen.getByLabelText('Personal access token')).toBeInTheDocument()\r\n    })\r\n\r\n    it('opens the config page from the toolbar', () => {\r\n        mockMatchMedia(false)\r\n        renderWindow()\r\n\r\n        fireEvent.click(screen.getByRole('button', { name: 'Config' }))\r\n\r\n        expect(screen.getByRole('heading', { name: 'Config' })).toBeInTheDocument()\r\n        expect(window.location.hash).toBe('#/config')\r\n    })\r\n\r\n    it('closes the config page and confirms a successful save', async () => {\r\n        mockMatchMedia(false)\r\n        renderWindow()\r\n\r\n        fireEvent.click(screen.getByRole('button', { name: 'Config' }))\r\n        fireEvent.click(screen.getByRole('switch', { name: 'Startup splash' }))\r\n        fireEvent.click(screen.getByRole('button', { name: 'Save' }))\r\n\r\n        await waitFor(() => {\r\n            expect(screen.queryByRole('heading', { name: 'Config' })).toBeNull()\r\n            expect(screen.getByRole('alert')).toHaveTextContent('Config saved')\r\n        })\r\n        expect(window.location.hash).toBe('')\r\n        expect(configService.get('react.showStartupSplash')).toBe(false)\r\n    })\r\n\r\n    it('opens the config page directly from the URL', () => {\r\n        window.location.hash = '#/config/desktop'\r\n        mockMatchMedia(false)\r\n        renderWindow()\r\n\r\n        expect(screen.getByRole('heading', { name: 'Config' })).toBeInTheDocument()\r\n        expect(screen.getByRole('tab', { name: 'Desktop' })).toBeInTheDocument()\r\n    })\r\n\r\n    it('populates the search query from a real agent run when the Electron bridge is available', async () => {\r\n        mockMatchMedia(false)\r\n        installAgentBridge('Beta')\r\n        renderWindow()\r\n\r\n        typeQuery('find the beta card')\r\n        fireEvent.click(screen.getByRole('button', { name: 'Ask agent to build a RegExp' }))\r\n\r\n        await waitFor(() => expect(screen.getByRole('textbox', { name: 'Search project' })).toHaveValue('Beta'))\r\n    })\r\n\r\n    it('does not recreate the search RegExp agent on window re-render', () => {\r\n        mockMatchMedia(false)\r\n        installAgentBridge('Beta')\r\n        const createSearchRegexpAgent = vi.spyOn(searchRegexpAgent, 'createSearchRegexpAgent')\r\n        const { rerender } = renderWindow()\r\n\r\n        rerender(mainWindowElement({ toolbarAction: <button type=\"button\">Changed</button> }))\r\n\r\n        expect(createSearchRegexpAgent).toHaveBeenCalledTimes(1)\r\n    })\r\n\r\n    it('reports the RegExp agent as unavailable without the Electron bridge', async () => {\r\n        mockMatchMedia(false)\r\n        delete window.md2Actions\r\n        renderWindow()\r\n\r\n        typeQuery('alpha only')\r\n        fireEvent.click(screen.getByRole('button', { name: 'Ask agent to build a RegExp' }))\r\n\r\n        await waitFor(() => expect(screen.getByText('RegExp agent is not available')).toBeInTheDocument())\r\n        expect(screen.getByRole('textbox', { name: 'Search project' })).toHaveValue('alpha only')\r\n    })\r\n})\r\n",
design\activity\card__e08c4b32-0bff-42a8-9df2-b0df009606ab.json:118:          "content": "import { Box, Button, Divider, MenuItem, Tab as MuiTab, Tabs, TextField, ToggleButton, ToggleButtonGroup, Tooltip } from '@mui/material'\r\nimport type { SelectChangeEvent } from '@mui/material'\r\nimport type { ChangeEvent, MouseEvent as ReactMouseEvent, ReactNode, SyntheticEvent } from 'react'\r\nimport { useCallback, useState } from 'react'\r\nimport CardsOutline from 'mdi-material-ui/CardsOutline'\r\nimport CheckCircleOutline from 'mdi-material-ui/CheckCircleOutline'\r\nimport CloudArrowDownOutline from 'mdi-material-ui/CloudArrowDownOutline'\r\nimport CloudArrowUpOutline from 'mdi-material-ui/CloudArrowUpOutline'\r\nimport Cog from 'mdi-material-ui/Cog'\r\nimport ContentSaveOutline from 'mdi-material-ui/ContentSaveOutline'\r\nimport FileDocumentPlusOutline from 'mdi-material-ui/FileDocumentPlusOutline'\r\nimport FolderOpen from 'mdi-material-ui/FolderOpen'\r\nimport TextBoxOutline from 'mdi-material-ui/TextBoxOutline'\r\nimport { defaultModelForProfile, findAgentProfile, mergeAgentProfiles, THINKING_LEVELS, validateThinkingLevel } from '../../../data/agent_profiles'\r\nimport { configService } from '../../../services/config/config_service'\r\nimport { writeDesktopConfigToBridge } from '../../../services/config/config_persistence'\r\nimport { projectSessionService } from '../../../services/project/project_session_service'\r\nimport { workspaceViewService, type WorkspaceViewMode } from '../../../services/project/workspace_view_service'\r\nimport { workspaceNavigationService } from '../../../services/project/workspace_navigation_service'\r\nimport { actionService } from '../../../services/actions/action_service'\r\nimport { dialogService } from '../../../services/dialog_service'\r\nimport { projectContext } from '../../../data/action_context'\r\nimport type { UseGithubAuthResult } from '../../../auth/use_github_auth'\r\nimport { useConfigValue, useHasDesktopConfig } from '../../hooks/use_config_value'\r\nimport { useProjectState } from '../../hooks/use_project_state'\r\nimport { useProjectPersistence } from '../../hooks/use_project_persistence'\r\nimport { useProjectConfig } from '../../hooks/use_project_config'\r\nimport { usePrimaryWorktreeStatus } from '../../hooks/use_worktrees'\r\nimport { useWorkspaceView } from '../../hooks/use_workspace_view'\r\nimport { ActionEntryPoints } from '../../actions/action_entry_points'\r\nimport { MainToolbar } from './main_toolbar'\r\nimport { GithubAuthToolbarButton } from '../github_auth_toolbar_button'\r\nimport { NO_DRAG_REGION } from '../drag_region'\r\nimport { BranchSwitchDialog } from '../project/branch_switch_dialog'\r\nimport { CompleteReleaseDialog } from '../project/complete_release_dialog'\r\nimport { NewCardDialog } from '../project/new_card_dialog'\r\nimport { ProjectOpenDialog } from '../project/project_open_dialog'\r\nimport { useProjectToolbarMenuActions } from '../project/use_project_toolbar_menu_actions'\r\nimport { Menu } from './menu'\r\nimport { BranchMenuSelect } from './branch_menu_select'\r\nimport { MenuIconButton } from './menu_icon_button'\r\nimport { MenuSelect } from './menu_select'\r\nimport { MobileCreateMenu } from './mobile_create_menu'\r\nimport { Section } from './section'\r\nimport { Tab } from './tab'\r\n\r\ntype AppMenuTab = 'home' | 'agents'\r\ntype ProjectDialogMode = 'open' | 'branch' | 'card' | 'release'\r\n\r\ninterface AppMenuProps {\r\n    accessToken: string | null\r\n    auth: UseGithubAuthResult\r\n    extraActions: ReactNode\r\n    isGithubAuthenticated: boolean\r\n    isMobile: boolean\r\n    onOpenConfig: () => void\r\n    onOpenMobileMenu: () => void\r\n    search: ReactNode\r\n}\r\n\r\nconst MENU_TABS: { label: string; value: AppMenuTab }[] = [\r\n    { label: 'Home', value: 'home' },\r\n    { label: 'Run', value: 'agents' },\r\n]\r\nconst PROJECT_CONTEXT = projectContext()\r\n\r\nfunction persistDesktopConfig() {\r\n    if (!configService.hasDesktopConfig()) return\r\n\r\n    writeDesktopConfigToBridge(configService.getDesktopValues())\r\n}\r\n\r\n/** Tabbed app menu hosting project, account and agent actions. */\r\nexport function AppMenu(props: AppMenuProps) {\r\n    const { accessToken, auth, extraActions, isGithubAuthenticated, isMobile, onOpenConfig, onOpenMobileMenu, search } = props\r\n    const { project } = useProjectState()\r\n    const { hasPendingPush, hasPendingSave } = useProjectPersistence()\r\n    const primaryWorktreeStatus = usePrimaryWorktreeStatus()\r\n    const projectConfig = useProjectConfig()\r\n    const { viewMode } = useWorkspaceView()\r\n    const [currentTab, setCurrentTab] = useState<AppMenuTab>('home')\r\n    const [dialogMode, setDialogMode] = useState<ProjectDialogMode | null>(null)\r\n    const agentProfiles = mergeAgentProfiles(useConfigValue('desktop.agentProfiles'))\r\n    const selectedAgent = useConfigValue('desktop.agent')\r\n    const selectedProfile = findAgentProfile(agentProfiles, selectedAgent)\r\n    const selectedModels = selectedProfile?.models ?? []\r\n    const configuredModel = useConfigValue('desktop.model')\r\n    const selectedThinkingLevel = useConfigValue('desktop.thinkingLevel')\r\n    const desktopAvailable = useHasDesktopConfig()\r\n    const selectedModel = configuredModel || (selectedProfile ? defaultModelForProfile(selectedProfile) : '')\r\n    const projectBranch = project?.branch ?? ''\r\n\r\n    const closeDialog = useCallback(() => {\r\n        setDialogMode(null)\r\n    }, [])\r\n\r\n    const openDialog = useCallback((mode: ProjectDialogMode) => {\r\n        setDialogMode(mode)\r\n    }, [])\r\n\r\n    const actions = useProjectToolbarMenuActions({\r\n        accessToken,\r\n        isGithubAuthenticated,\r\n        onCloseDialog: closeDialog,\r\n        onOpenDialog: openDialog,\r\n    })\r\n    const branchOptions = actions.branches.length > 0 ? actions.branches : (project ? [{ name: project.branch }] : [])\r\n    const selectedBranch = branchOptions.some((branch) => branch.name === actions.switchBranch) ? actions.switchBranch : projectBranch\r\n\r\n    const handleTabChange = (_event: SyntheticEvent, value: AppMenuTab) => {\r\n        setCurrentTab(value)\r\n    }\r\n\r\n    const handleOpenProject = () => {\r\n        actions.openProjectDialog()\r\n    }\r\n\r\n    const handleCreateProjectFolders = (projectFolder: string) => {\r\n        void actions.createProjectFolders(projectFolder)\r\n    }\r\n\r\n    const handleLoadBranches = () => {\r\n        void actions.loadSwitchBranches()\r\n    }\r\n\r\n    const handleBranchChange = (event: SelectChangeEvent) => {\r\n        void actions.switchProjectBranch(event.target.value)\r\n    }\r\n\r\n    const handleOpenReleaseDialog = () => {\r\n        openDialog('release')\r\n    }\r\n\r\n    const handleOpenCardDialog = () => {\r\n        openDialog('card')\r\n    }\r\n\r\n    const handleCommit = async () => {\r\n        try {\r\n            await actions.commit()\r\n        } catch {\r\n            // ProjectSessionService emits the user-visible error.\r\n        }\r\n    }\r\n\r\n    const handlePush = async () => {\r\n        try {\r\n            await actions.push()\r\n        } catch {\r\n            // ProjectSessionService emits the user-visible error.\r\n        }\r\n    }\r\n\r\n    const handlePull = async () => {\r\n        try {\r\n            await actions.pull()\r\n        } catch {\r\n            // ProjectSessionService emits the user-visible error.\r\n        }\r\n    }\r\n\r\n    const handleViewModeChange = (_event: ReactMouseEvent<HTMLElement>, nextMode: WorkspaceViewMode | null) => {\r\n        if (!nextMode) return\r\n\r\n        workspaceViewService.setViewMode(nextMode)\r\n    }\r\n\r\n    const handleAgentChange = (event: SelectChangeEvent) => {\r\n        const profile = findAgentProfile(agentProfiles, event.target.value)\r\n        const nextModel = profile ? defaultModelForProfile(profile) : ''\r\n        configService.set('desktop.agent', event.target.value)\r\n        configService.set('desktop.model', nextModel)\r\n        persistDesktopConfig()\r\n    }\r\n\r\n    const setModel = (value: string) => {\r\n        configService.set('desktop.model', value)\r\n        persistDesktopConfig()\r\n    }\r\n\r\n    const handleModelSelectChange = (event: SelectChangeEvent) => {\r\n        setModel(event.target.value)\r\n    }\r\n\r\n    const handleModelTextChange = (event: ChangeEvent<HTMLInputElement>) => {\r\n        setModel(event.target.value)\r\n    }\r\n\r\n    const handleThinkingLevelChange = (event: SelectChangeEvent) => {\r\n        const thinkingLevel = validateThinkingLevel(event.target.value, 'Default reasoning level')\r\n        configService.set('desktop.thinkingLevel', thinkingLevel)\r\n        persistDesktopConfig()\r\n    }\r\n\r\n    const handleCreateAction = async () => {\r\n        if (!projectConfig) throw new Error('Cannot create an action before project config is loaded')\r\n\r\n        try {\r\n            const { definition, path } = actionService.createDefinition(projectConfig.actionsFolder)\r\n            await actionService.saveDefinition(path, definition)\r\n            workspaceViewService.setViewMode('text')\r\n            workspaceNavigationService.open(path)\r\n        } catch (error) {\r\n            dialogService.error(error, { fallbackMessage: 'Action creation failed' })\r\n        }\r\n    }\r\n\r\n    const handleDiscardGithubPendingCommits = () => {\r\n        if (!actions.pendingGithubConflictProject) return\r\n\r\n        projectSessionService.discardGithubPendingCommits(actions.pendingGithubConflictProject, accessToken)\r\n    }\r\n\r\n    const menuTabs = (\r\n        <Tabs\r\n            aria-label=\"Application menu\"\r\n            onChange={handleTabChange}\r\n            scrollButtons={false}\r\n            sx={{\r\n                minHeight: 44,\r\n                '& .MuiTabs-indicator': { height: 2 },\r\n            }}\r\n            value={currentTab}\r\n            variant=\"scrollable\"\r\n        >\r\n            {MENU_TABS.map((tab) => (\r\n                <MuiTab\r\n                    key={tab.value}\r\n                    label={tab.label}\r\n                    sx={{ fontSize: 13.5, minHeight: 44, minWidth: 0, px: 1.5, textTransform: 'none' }}\r\n                    value={tab.value}\r\n                />\r\n            ))}\r\n        </Tabs>\r\n    )\r\n\r\n    const viewSection = (\r\n        <Section label=\"View\">\r\n            <ToggleButtonGroup\r\n                exclusive\r\n                onChange={handleViewModeChange}\r\n                size=\"small\"\r\n                sx={{\r\n                    bgcolor: 'action.selected',\r\n                    borderRadius: 1,\r\n                    gap: 0.25,\r\n                    p: 0.375,\r\n                    '& .MuiToggleButtonGroup-grouped': { border: 0, borderRadius: '6px !important', height: 28, px: 1.25 },\r\n                    '& .Mui-selected': { bgcolor: 'background.paper', boxShadow: '0 1px 2px rgba(16,24,40,0.1)' },\r\n                }}\r\n                value={viewMode}\r\n            >\r\n                <Tooltip title=\"Cards view\">\r\n                    <ToggleButton aria-label=\"Cards view\" value=\"cards\">\r\n                        <CardsOutline fontSize=\"small\" />\r\n                        <Box component=\"span\" sx={{ ml: 0.75 }}>Board</Box>\r\n                    </ToggleButton>\r\n                </Tooltip>\r\n                <Tooltip title=\"Text view\">\r\n                    <ToggleButton aria-label=\"Text view\" value=\"text\">\r\n                        <TextBoxOutline fontSize=\"small\" />\r\n                        <Box component=\"span\" sx={{ ml: 0.75 }}>List</Box>\r\n                    </ToggleButton>\r\n                </Tooltip>\r\n            </ToggleButtonGroup>\r\n        </Section>\r\n    )\r\n\r\n    const menuPanel = (\r\n        <Menu>\r\n            <Box role=\"tabpanel\" sx={{ dis